const data = resp.data;

const lastYear = data[0] ? libs.d3.max(data, d => d["Year"]) : false
const shipments = data.filter(d => d["Year"] === lastYear)[0] ? data.filter(d => d["Year"] === lastYear)[0]["Count"] : false

return{
    lastYear,
    shipments: formatters.commas(shipments)
}

const {name1} = variables;
const {commas} = formatters;

// Has Bol
const data = resp ? resp.data : [];
const hasBolData = data.length > 0;

if(hasBolData){

    const lastMonth = libs.d3.max(data, d => d["Time"])
    const prevMonth = lastMonth - 100
    const prev3Years = lastMonth - 300

    const shipmentLastMonth = data.filter(d => d.Time === lastMonth)[0] ? data.filter(d => d.Time === lastMonth)[0]["Count"] : false
    const shipmentPrevMonth = data.filter(d => d.Time === prevMonth)[0] ? data.filter(d => d.Time === prevMonth)[0]["Count"] : false
    const shipmentPrev3Years = data.filter(d => d.Time === prev3Years)[0] ? data.filter(d => d.Time === prev3Years)[0]["Count"] : false

    const growthShipments = ((shipmentLastMonth - shipmentPrevMonth) / shipmentPrevMonth) * 100
    const cagr = shipmentPrev3Years ? (((shipmentLastMonth / shipmentPrev3Years) ** (1 / 3)) - 1) * 100 : false
    const cagrFormatted = formatters.growthPct(cagr)
    const cagrAbs = formatters.growthPct(Math.abs(cagr))

    translations = {
        cagr: {en: `Over the past 3 years, ${name1} had a compound annual growth rate (CAGR) of approximately ${cagrFormatted}. `, es: `En los últimos 3 años ${name1} tuvo una tasa de crecimiento anual compuesta (CAGR) de aproximadamente el ${cagrFormatted}. `, zh: `过去3年中，${name1}的复合年增长率 (CAGR) 约为${cagrFormatted}。`},
        increase: {en: `Over the past 3 years, the compound annual growth rate (CAGR) of shipments received by ${name1} increased by approximately ${cagrFormatted}.`, es: `En los últimos 3 años, la tasa de crecimiento anual compuesta (CAGR) de los envíos recibidos por ${name1} aumentó aproximadamente ${cagrFormatted}.`, zh: `过去3年中，${name1}收到的货物的复合年增长率 (CAGR) 增加了约${cagrFormatted}。`},
        decrease: {en: `Over the past 3 years, the compound annual growth rate (CAGR) of shipments received by ${name1} decreased by approximately ${cagrFormatted}.`, es: `En los últimos 3 años, la tasa de crecimiento anual compuesta (CAGR) de los envíos recibidos por ${name1} disminuyó aproximadamente ${cagrFormatted}.`, zh: `过去3年中，${name1}收到的货物的复合年增长率 (CAGR) 下降了约${cagrFormatted}。`},
    }

    const textCagr = cagr ? (cagr > 0 ? `${translations["increase"][locale]}` : `${translations["decrease"][locale]}`) : ""
    const textCagr2 = cagr ? (`${translations["cagr"][locale]}`) : ""

    return{
        lastMonth: formatters.monthName(lastMonth),
        prevMonth: formatters.monthName(prevMonth),
        growthShipments: formatters.growthPct(growthShipments),
        shipmentLastMonth: commas(shipmentLastMonth),
        shipmentPrevMonth: commas(shipmentPrevMonth),
        cagr: textCagr2,
        textCagr,
    }
}
else{
    return{
        lastMonth: false
    }
}

