const data = resp.data;
const {ENV_PROFILE_PREFIX, totalShipments} = variables;
const {growthPct, list, monthName} = formatters;

if(data.length > 0){
    data.forEach(d => {
        d["Share"] = `${growthPct((d.Count / totalShipments) * 100)}`
    })

    const topProductsEN =  data.slice(0,3).map(d => `<a href="/${locale}${ENV_PROFILE_PREFIX}${d.bespoke_slug}">${d["HS4"]}</a> with ${formatters.commas(d["Count"])} shipments (${d["Share"]} of the total)`);
    const topProductsES =  data.slice(0,3).map(d => `<a href="/${locale}${ENV_PROFILE_PREFIX}${d.bespoke_slug}">${d["HS4"]}</a> con ${formatters.commas(d["Count"])} envíos (${d["Share"]} del total)`);
    const topProductsZH =  data.slice(0,3).map(d => `<a href="/${locale}${ENV_PROFILE_PREFIX}${d.bespoke_slug}">${d["HS4"]}</a>共包含${formatters.commas(d["Count"])}批货物（占总量的${d["Share"]}）`);
    const topProducts = locale === "en" ? topProductsEN : locale === "es" ? topProductsES : topProductsZH

    const lastDateProducts = data[0] ? data[0]["Time"] : false

    const lastMonthFormatted = monthName(lastDateProducts)
    const lastMonth = lastMonthFormatted.split(" ")[0]

    return{
        topProducts: list(topProducts),
        lastDateProducts: monthName(lastDateProducts),
        lastYear: lastDateProducts.toString().slice(0,4),
        lastMonth
    }
}
else{
    return{
        topProducts: false,
        lastDateProducts: false,
        lastYear: false
    }
}

