    const topDestination =  data.slice(0,1).map(d => `<a href='/${locale}${ENV_PROFILE_PREFIX}${d.bespoke_slug}'>${d["Subnat Geography"]}</a> (${commas(d["Count"])} ${shipments[locale]}, ${growthPct((d["Count"]/total)*100)} of the total)`);

