const data = resp.data;

const totalShipments = libs.d3.sum(data, d => d.Count)

return{
    totalShipments
}

return {
  component: "selector",
  defaultValue: variables["defaultMeasure"],
  hideLabel: "false",
  name: "Size by:",
  options: (variables["measuresAvailable"] || []).map(d => ({id: String(d["option"]), label: String(d["label"]), imageUrl: String(d["null"])})),
  resetSectionVars: "false",
