const {selector1389id, selector1391id} = variables;
const data = resp.data.filter(d => d.Year >= 2020 && d[selector1389id] > 0);

const lastYear = libs.d3.max(data, d => d.Year)
const lastMonthAvailable = libs.d3.max(data, d => d.Time)

const translation = {
  year: {en: "Year", es: "Año", zh: "年"},
  quarter: {en: "Quarter", es: "Trimestre", zh: "四分之一"},
  month: {en: "Month", es: "Mes", zh: "月"},
}

data.forEach(d => {
  d["Month ID"] = d.Time
  d["Month"] = formatters.monthName(d.Time)
  d["Year ID"] = d.Year
  d["Quarter ID"] = `${d.Year}${d["Quarter ID"]}`*1
  d.Quarter = formatters.time(d["Quarter ID"])
  delete d.Time
})

const minMonth = libs.d3.min(data, d => d["Month ID"])
const dataFiltered = selector1391id === "tradeOption" ? data : data.filter(d => d["Month ID"] >= minMonth + 100)

const levels = [
  {
    label: `${translation["year"][locale]}`,
    value: "Year",
  },
  {
    label: `${translation["quarter"][locale]}`,
    value: "Quarter",
  },
  {
    label: `${translation["month"][locale]}`,
    value: "Month",
  },
];

const defaultValue = {
  type: "Year",
  value: [lastYear.toString()],
};

return {
    timeList: dataFiltered,
    timeLevels: levels,
    timeDefault: defaultValue,
    lastMonthAvailable
}

