const topCountryInfoEN = data[0] ? `<a href='/${locale}${ENV_PROFILE_PREFIX}${data[0].bespoke_slug}'>${data[0]["Country"]}</a> (${formatter(data[0][selector1389id])}${unitsEN}, ${growthPct((data[0][selector1389id]/total)*100)} of the total)` : false
const topCountryInfoES = data[0] ? `<a href='/${locale}${ENV_PROFILE_PREFIX}${data[0].bespoke_slug}'>${data[0]["Country"]}</a> (${formatter(data[0][selector1389id])} ${unitsES}, ${growthPct((data[0][selector1389id]/total)*100)} del total)` : false
const topCountryInfoZH = data[0] ? `<a href='/${locale}${ENV_PROFILE_PREFIX}${data[0].bespoke_slug}'>${data[0]["Country"]}</a>（${formatter(data[0][selector1389id])}${unitsZH}, ${growthPct((data[0][selector1389id]/total)*100)}）` : false
const topCountryInfo = locale === "en" ? topCountryInfoEN : locale === "es" ? topCountryInfoES : topCountryInfoZH

const topCountryName =data[0] ? `<a href='/${locale}${ENV_PROFILE_PREFIX}${data[0].bespoke_slug}'>${data[0]["Country"]}</a>` : false


