const data = resp.data;

const translation = {
    Count: {en: "Number of Shipments", es: "Número de envíos", zh: "发货数量"},
    TEU: {en: "TEU (Twenty-foot Equivalent Unit)", es: "TEU (Unidad equivalente a veinte pies)", zh: "TEU（二十英尺标准箱）"},
    CIF: {en: "CIF (Cost, Insurance, and Freight)", es: "CIF (Costo, seguro y flete)", zh: "CIF（成本、保险和运费）"},
}

const pivotedData = data.flatMap(d => 
    ["Count", "TEU", "CIF"].map(measure => ({
        Company: d["Consignee Name"],
        Measure: measure,
        Name: `${translation[measure][locale]}`,
        Value: d[measure]
    }))
)

const dataForOption = pivotedData.filter(d => d.Value !== 0)

let measuresAvailable = dataForOption.map(d => ({
  "label": d.Name,
  "option": d.Measure
}));


return{
   measuresAvailable,
   defaultMeasure: "Count" 
}

const {page} = resp;
return {
    SECTION_ALLOWED: page && page.total && page.total > 0 ? true : false
}

// Has Bol
const dataBol = resp && resp[0] ? resp[0].data : [];

// Has Digital Trade
const dataDigitalTrade = resp && resp[1] ? resp[1].data : [];

return{
    hasBolData: dataBol.length > 0,
    hasDigitalTradeData: dataDigitalTrade.length > 0,
}

const {data} = resp;
const dtYears = data.map(d => d.Year).sort();
return {
