    dtLatestYear: dtYears.length > 0 ? dtYears[dtYears.length -1] : false
}

const data = resp.data;

const lastYear = data[0] ? libs.d3.max(data, d => d.Year) : false
const topProduct = data[0] ? data[0]["Specific level"] : false
