const {ENV_PROFILE_PREFIX} = variables;
const data = resp.data.filter(d => d["Exporter Country ID"] !== null);

const topExporterName = data[0] ? `<a href='/${locale}${ENV_PROFILE_PREFIX}${data[0].bespoke_slug}'>${data[0]["Exporter Country"]}</a>` : false
