const data = resp.data.filter(d => d["Importer Country ID"] !== null);
const {ENV_PROFILE_PREFIX} = variables;
const {dollar} = formatters;

if(data.length > 0){

    const topImporterName = data[0] ? `<a href='/${locale}${ENV_PROFILE_PREFIX}${data[0].bespoke_slug}'>${data[0]["Importer Country"]}</a>` : false
    const topImporterValue = data[0] ? data[0]["Trade Value HQ"] : false
    const lastYear = data[0] ? data[0]["Year"] : false

    const topImporterList = data[0] ? data.map(d => `<a href='/${locale}${ENV_PROFILE_PREFIX}${d.bespoke_slug}'>${d["Importer Country"]}</a> (${dollar(d["Trade Value HQ"])})`) : false

    return{
        lastYear,
        topImporterName,
        topImporterList: formatters.list(topImporterList),
        topImporterValue: formatters.dollar(topImporterValue)
    }
}
else{
    return{
        lastYear: false,
    }
}

const {name1} = variables;
const {commas, dollar} = formatters;

// Has Digital
const data = resp ? resp.data : [];
const hasDigital = data.length > 0;

if(hasDigital){

    // Helper: encuentra el dato cuyo Year esté más cerca de un año objetivo,
    // sin pasarse del año objetivo (busca hacia atrás), y sin incluir lastYear.
    const findClosestYear = (targetYear, excludeYear) => {
        const candidates = data.filter(d => d.Year !== excludeYear && d.Year <= excludeYear - 1)
        if(candidates.length === 0) return false
        // el más cercano a targetYear, priorizando <= targetYear si existe
        let closest = candidates[0]
        let minDiff = Math.abs(candidates[0].Year - targetYear)
        for(const d of candidates){
            const diff = Math.abs(d.Year - targetYear)
            if(diff < minDiff){
                minDiff = diff
                closest = d
            }
        }
        return closest
    }

    const lastYear = libs.d3.max(data, d => d.Year)
    const targetPrevYear = lastYear - 1
    const targetPrev3Years = lastYear - 3

    const lastYearEntry = data.filter(d => d.Year === lastYear)[0]
    const digitalLastYear = lastYearEntry ? lastYearEntry["Trade Value HQ"] : false

    const prevYearEntry = data.filter(d => d.Year === targetPrevYear)[0] || findClosestYear(targetPrevYear, lastYear)
    const prevYear = prevYearEntry ? prevYearEntry.Year : false
    const digitalPrevYear = prevYearEntry ? prevYearEntry["Trade Value HQ"] : false

    const prev3YearsEntry = data.filter(d => d.Year === targetPrev3Years)[0] || findClosestYear(targetPrev3Years, lastYear)
    const prev3Years = prev3YearsEntry ? prev3YearsEntry.Year : false
    const digitalPrev3Years = prev3YearsEntry ? prev3YearsEntry["Trade Value HQ"] : false

    const growthDigital = (digitalPrevYear && digitalPrevYear !== 0) ? ((digitalLastYear - digitalPrevYear) / digitalPrevYear) * 100 : false
    const growthDigitalFormatted = growthDigital !== false ? formatters.growthPct(growthDigital) : ""

    // nYears reales entre lastYear y el año base del CAGR (evita asumir siempre 3)
    const nYears = (prev3Years && prev3Years !== lastYear) ? (lastYear - prev3Years) : false
    const cagr = (digitalPrev3Years && nYears) ? (((digitalLastYear / digitalPrev3Years) ** (1 / nYears)) - 1) * 100 : false
    const cagrFormatted = cagr !== false ? formatters.growthPct(cagr) : ""
    const cagrAbs = cagr !== false ? formatters.growthPct(Math.abs(cagr)) : ""

    const translations = {
        cagr: {en: `Over the past ${nYears} years, ${name1}'s digital commerce experienced  a compound annual growth rate (CAGR) of approximately ${cagrFormatted}. `, es: `En los últimos ${nYears} años, el comercio digital de ${name1} experimentó una tasa de crecimiento anual compuesta (CAGR) de aproximadamente ${cagrFormatted}. `, zh: `在过去${nYears}年中，${name1}的数字商务的复合年增长率 (CAGR) 约为${cagrFormatted}。`},
        increase: {en: `Over the past ${nYears} years, the digital product exports of ${name1} grew at a compound annual growth rate (CAGR) of approximately ${cagrFormatted} (from ${dollar(digitalPrev3Years)} to ${dollar(digitalLastYear)}). `, es: `Durante los últimos ${nYears} años, las exportaciones de productos digitales de ${name1} crecieron a una tasa de crecimiento anual compuesta (CAGR) de aproximadamente ${cagrFormatted} (de ${dollar(digitalPrev3Years)} a ${dollar(digitalLastYear)}). `, zh: `过去${nYears}年，${name1}的数字产品出口以大约${cagrFormatted}的复合年增长率（CAGR）增长（从${dollar(digitalPrev3Years)}到${dollar(digitalLastYear)}）。`},
        decrease: {en: `Over the past ${nYears} years, the digital product exports of ${name1} declined at a compound annual growth rate (CAGR) of approximately ${cagrFormatted} (from ${dollar(digitalPrev3Years)} to ${dollar(digitalLastYear)}). `, es: `En los últimos ${nYears} años, las exportaciones de productos digitales de ${name1} disminuyeron a una tasa de crecimiento anual compuesta (CAGR) de aproximadamente ${cagrFormatted} (de ${dollar(digitalPrev3Years)} a ${dollar(digitalLastYear)}). `, zh: `过去${nYears}年，${name1}的数字产品出口以约${cagrFormatted}的复合年增长率（CAGR）下降（从${dollar(digitalPrev3Years)}到${dollar(digitalLastYear)}）。`},
    }

    const textCagrDigital = cagr !== false ? (cagr > 0 ? `${translations["increase"][locale]}` : `${translations["decrease"][locale]}`) : ""
    const textCagr2 = cagr !== false ? (`${translations["cagr"][locale]}`) : ""

    const trend = {
        en: "Stojkoski et al. (2024)",
        es: "Stojkoski et al. (2024)",
        zh: "Stojkoski 等人（2024）"
    }
    const link = `<a href='https://www.nature.com/articles/s41467-024-49141-z'>${trend[locale]}</a>`

    const mainText = {
        en: `For ${lastYear}, we estimate the digital product exports of ${name1} to be ${dollar(digitalLastYear)}. ${growthDigitalFormatted ? `This represents a year-over-year change of ${growthDigitalFormatted}. ` : ""}${textCagrDigital}We base our digital product trade estimates on the methodology developed by ${link}.`,
        es: `Para ${lastYear}, estimamos que las exportaciones de productos digitales de ${name1} fueron de ${dollar(digitalLastYear)}. ${growthDigitalFormatted ? `Esto representa un cambio interanual de ${growthDigitalFormatted}. ` : ""}${textCagrDigital}Basamos nuestras estimaciones de comercio de productos digitales en la metodología desarrollada por ${link}.`,
        zh: `${lastYear}年，我们估计${name1}的数字产品出口额为${dollar(digitalLastYear)}。${growthDigitalFormatted ? `这代表同比变化为${growthDigitalFormatted}。` : ""}${textCagrDigital}我们的数字产品贸易估计基于${link}开发的方法。`
    }

    return{
        link,
        lastYearDigital: lastYear,
        prevYearDigital: prevYear,
        growthDigital: growthDigitalFormatted,
        digitalLastYear: dollar(digitalLastYear),
