const backgroundImageV2 = (key, d) => {
  const options = {2: "export", 1: "import", 3: "trade_balance"};

  switch (key) {
    case "Continent":
      return `/images/icons/country/country_${d["Continent ID"]}.png`;
    case "Country":
      if (Array.isArray(d["Country ID"])) {
        return `/images/icons/country/country_${d["Continent ID"]}.png`;
      }

      return `/images/icons/country/country_${d["ISO 3"] || d["Country ID"].slice(2, 5)}.png`;

    // case "Subnat Geography":
    //   if(isDeu(d["Subnat Geography"])) {
    //     return `/images/icons/subnational/deu/flag_${d["Subnat Geography ID"] || 1}.png`;
    //   }
    //   return null
    case "Flow":
    case "Trade Flow":
      return `/images/icons/balance/${options[d[`${key} ID`]]}_val.png`;
    case "Organization":
      return "/images/icons/patent.png";
    case "Section":
      return `/images/icons/hs/hs_${d["Section ID"]}.svg`;
    case "Category":
      return `/images/icons/sitc/sitc_${d["Category ID"]}.png`;
    case "SITC Section":
      if (d["Section ID"] === 100) {
        return `/images/icons/balance/${options[3]}_val.png`;
      }
      return !isNaN(d["Section ID"])
        ? `/images/icons/sitc/sitc_${d["Section ID"]}.svg` : "/images/icons/sitc/sitc_X.svg";
    case "EGW1":
      return `/images/icons/egw/egw_${d["EGW1 ID"]}.svg`;
    case "Level 1":
      return `/images/icons/cpf/cpf_${d["Level 1 ID"]}.svg`;
    case "Service":
    case "Parent Service":
      return `/images/icons/service/service_${[d[`${key} ID`]]}.png`;
    default:
      return "/images/icons/hs/hs_22.svg";
  }
};

const findColorV2 = (key, d) => {
  if (key === "Country" || key === "ISO 3") {
    if (!Array.isArray(d["Country ID"])) return "transparent";
    return colors.Continent[d["Continent ID"]];
  }
  // if (key === "Subnat Geography" && isDeu(d["Subnat Geography"])) {
  //   return "transparent";
  // }
  const id = key === "SITC Section" ? d["Section ID"] : d[`${key} ID`];
  const palette = colors[key];

  return palette ? colors[key][id] || colors[key][d[key]] || colors.colorGrey : colors.colorGrey;
};


const tooltipTitle = ([key, d, optional]) => {
  const bgColor = findColorV2(key, d); // find the color based on the key and object
  const imgUrl = backgroundImageV2(key, d); // find the background image based on the key and object
  const title = d[optional] || key; // the key is used as the title

  let tooltip = "<div class='d3plus-tooltip-title-wrapper'>";

  if (bgColor && imgUrl) {
    tooltip += `<div class="icon" style="background-color: ${bgColor};"><img src="${imgUrl}" alt="icon" /></div>`;
  } else if (bgColor) {
    tooltip += `<div class="icon" style="background-color: ${bgColor};">&nbsp;</div>`;
  }

  tooltip += `<div class="title"><span>${title}</span></div>`;
  tooltip += "</div>";

  return tooltip;
};

