const formatOrdinal = (number, locale = 'en') => {
  const suffixes = {
    en: ['th', 'st', 'nd', 'rd'],
    es: ['º', 'º', 'º', 'º'], // Spanish uses "º" for ordinal numbers
    zh: ['第'],              // Chinese uses "第" prefix for ordinal numbers
  };

  const mod100 = number % 100;
  let suffix = '';

  if (locale === 'en') {
    suffix = suffixes.en[(mod100 - 20) % 10] || suffixes.en[mod100] || suffixes.en[0];
  } else if (locale === 'es') {
    suffix = suffixes.es[0]; // Spanish ordinal suffix is constant ("º")
  } else if (locale === 'zh') {
    return `${suffixes.zh[0]}${number}`; // Prefix for Chinese ordinal
  }

  return `${number}<sup>${suffix}</sup>`;
};

return formatOrdinal(n, locale)

function numberToName(n, lang) {
    const numberNames = {
        en: [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
            "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", 
            "seventeen", "eighteen", "nineteen", "twenty"
        ],
        es: [
            "cero", "uno", "dos", "tres", "cuatro", "cinco", "seis", "siete", "ocho", "nueve",
            "diez", "once", "doce", "trece", "catorce", "quince", "dieciséis", "diecisiete", 
            "dieciocho", "diecinueve", "veinte"
        ],
        zh: [
            "零", "一", "二", "三", "四", "五", "六", "七", "八", "九",
            "十", "十一", "十二", "十三", "十四", "十五", "十六", "十七", 
            "十八", "十九", "二十"
        ]
    };

    if (n >= 0 && n <= 20 && numberNames[lang]) {
        return numberNames[lang][n];
    }

    return n;
}

return numberToName(n, locale)

const version = { en: "en-US", es: "es-CL", zh: "zh-CN" };

function formatAbbrevWithCurrency([n, locale = "en", currency = "$"]) {
  const sign = n < 0 ? "-" : "";
  const absValue = Math.abs(n);

  return `${sign}${currency}${libs.d3plus
    .formatAbbreviate(absValue, version[locale])
    .replace("t", "T")}`;
}

return formatAbbrevWithCurrency(n)

function calculateSymmetricRange(n) {
  const values = n[0].map(d => d[n[1]]);

  const absValues = values.map(Math.abs);
  const maxAbsValue = Math.max(...absValues);
  const limit = maxAbsValue * n[2];

  const roundedLimit = Math.ceil(limit * 10) / 10;

  return [-roundedLimit, roundedLimit];
}

const range = calculateSymmetricRange(n);

return range

